 if row['scope']=='native':assert p['lookback_days']==row['lookback_days'] in [3,4] and p['slow_return_hurdle_fraction']==row['slow_return_hurdle_fraction'] and p['fixed_entry_notional_usdt']==3000 and p['trend_gate_lookbacks_days']==[p['trend_lookback_days']-1,p['trend_lookback_days'],p['trend_lookback_days']+1]
